// Test helpers for the real-ffmpeg fixtures generated by `pnpm fixtures` into .local/fixtures.
import { existsSync } from 'node:fs';
import { copyFile, mkdir, mkdtemp, utimes } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Capabilities } from '@transcoda/contract';
import { probeFfmpeg } from '../capabilities/ffmpeg.ts';

const REPO_ROOT = fileURLToPath(new URL('../../../../', import.meta.url));
const FIXTURES_DIR = join(REPO_ROOT, '.local', 'fixtures');
const TMP_DIR = join(REPO_ROOT, '.local', 'tmp');

export type FixtureName =
  | 'tigger-pooh.mp4'
  | 'compliant.mkv'
  | 'untagged.mkv'
  | 'pgs-subs.mkv'
  | 'ass-fonts.mkv'
  | 'two-defaults.mkv'
  | 'h264-big.mkv'
  | 'no-default-audio.mkv'
  | 'two-defaults-h264.mkv'
  | 'no-default-sub.mkv';

const HARDWARE_ENCODER = /_(nvenc|qsv|vaapi|videotoolbox|amf)$/;

/** True when `pnpm fixtures` has run (its manifest exists). */
export function fixturesAvailable(): boolean {
  return existsSync(join(FIXTURES_DIR, 'manifest.json'));
}

export function fixturePath(name: FixtureName): string {
  return join(FIXTURES_DIR, name);
}

export function toolPaths(): { ffmpegPath: string; ffprobePath: string } {
  return {
    ffmpegPath: process.env.TRANSCODA_FFMPEG_PATH || 'ffmpeg',
    ffprobePath: process.env.TRANSCODA_FFPROBE_PATH || 'ffprobe',
  };
}

/** A fresh directory under .local/tmp/; the caller removes it in its afterAll. */
export async function tempDir(prefix: string): Promise<string> {
  await mkdir(TMP_DIR, { recursive: true });
  return mkdtemp(join(TMP_DIR, prefix));
}

/**
 * Copies a fixture into `destDir` (as `as`, default its own name) and backdates its mtime by an
 * hour, so the settle window never sees it as still growing. Returns the new path.
 */
export async function copyFixture(
  name: FixtureName,
  destDir: string,
  as?: string,
): Promise<string> {
  const dest = join(destDir, as ?? name);
  await copyFile(fixturePath(name), dest);
  const past = new Date(Date.now() - 60 * 60 * 1000);
  await utimes(dest, past, past);
  return dest;
}

/** The local ffmpeg's capabilities without hardware encoders, so `auto` picks libx265/libx264. */
export async function realCapabilities(): Promise<Capabilities> {
  const caps = await probeFfmpeg(toolPaths().ffmpegPath);
  if (!caps.available) return caps;
  return {
    ...caps,
    encoders: caps.encoders.filter((e) => !HARDWARE_ENCODER.test(e)),
    hwaccels: [],
  };
}
